import {test} from 'node:test';
import assert from 'node:assert/strict';
import {applyDiscount} from '../src/discount.mjs';

test('hidden check', async () => {
  assert.equal(applyDiscount(12345, 'silver'), 11900);
  assert.equal(applyDiscount(10000, 'gold'), 9300);
  assert.equal(applyDiscount(99, 'normal'), 0);
  assert.throws(() => applyDiscount(10.5, 'gold'), /invalid_amount/);
});
